// =============================================================================
// SECTION 1 — Value: scalar autograd engine (replaces the Python Value class)
// =============================================================================

use std::cell::RefCell;
use std::collections::HashSet;
use std::fmt;
#[cfg(feature = "plot")]
use std::fs;
use std::rc::Rc;
use std::sync::atomic::{AtomicU64, Ordering};

/// Internal mutable state of a single scalar node in the computation graph.
struct ValueInner {
    data: f64,
    grad: f64,
    label: String,
    op: String,
    prev: Vec<Value>,
    backward_fn: Option<Box<dyn Fn()>>,
}

/// A reference-counted, interior-mutable scalar value with autograd support.
/// This is the direct equivalent of the Python `Value` class.
#[derive(Clone)]
pub struct Value(Rc<RefCell<ValueInner>>);

impl Value {
    // ------------------------------------------------------------------
    // Constructor
    // ------------------------------------------------------------------
    pub fn new(data: f64) -> Self {
        Value(Rc::new(RefCell::new(ValueInner {
            data,
            grad: 0.0,
            label: String::new(),
            op: String::new(),
            prev: vec![],
            backward_fn: None,
        })))
    }

    pub fn with_label(data: f64, label: &str) -> Self {
        let v = Self::new(data);
        v.set_label(label);
        v
    }

    // ------------------------------------------------------------------
    // Accessors
    // ------------------------------------------------------------------
    pub fn data(&self) -> f64 {
        self.0.borrow().data
    }

    pub fn grad(&self) -> f64 {
        self.0.borrow().grad
    }

    pub fn set_data(&self, d: f64) {
        self.0.borrow_mut().data = d;
    }

    pub fn set_grad(&self, g: f64) {
        self.0.borrow_mut().grad = g;
    }

    pub fn set_label(&self, l: &str) {
        self.0.borrow_mut().label = l.to_string();
    }

    pub fn label(&self) -> String {
        self.0.borrow().label.clone()
    }

    // Used so HashSet can identify nodes by pointer identity (same as Python id())
    fn ptr_id(&self) -> usize {
        Rc::as_ptr(&self.0) as usize
    }

    // ------------------------------------------------------------------
    // Arithmetic operations  (mirrors __add__, __mul__, __pow__, etc.)
    // ------------------------------------------------------------------

    /// Addition:  self + other
    pub fn add(&self, other: &Value) -> Value {
        let out = Value::new(self.data() + other.data());
        out.0.borrow_mut().op = "+".into();
        out.0.borrow_mut().prev = vec![self.clone(), other.clone()];

        let s = self.clone();
        let o = other.clone();
        let out_ref = out.clone();
        out.0.borrow_mut().backward_fn = Some(Box::new(move || {
            let og = out_ref.grad();
            s.0.borrow_mut().grad += og;
            o.0.borrow_mut().grad += og;
        }));
        out
    }

    /// Multiplication: self * other
    pub fn mul(&self, other: &Value) -> Value {
        let out = Value::new(self.data() * other.data());
        out.0.borrow_mut().op = "*".into();
        out.0.borrow_mut().prev = vec![self.clone(), other.clone()];

        let s = self.clone();
        let o = other.clone();
        let out_ref = out.clone();
        out.0.borrow_mut().backward_fn = Some(Box::new(move || {
            let og = out_ref.grad();
            s.0.borrow_mut().grad += o.data() * og;
            o.0.borrow_mut().grad += s.data() * og;
        }));
        out
    }

    /// Power: self ^ exp  (integer or float exponent)
    pub fn pow(&self, exp: f64) -> Value {
        let out = Value::new(self.data().powf(exp));
        out.0.borrow_mut().op = format!("**{}", exp);
        out.0.borrow_mut().prev = vec![self.clone()];

        let s = self.clone();
        let out_ref = out.clone();
        out.0.borrow_mut().backward_fn = Some(Box::new(move || {
            let og = out_ref.grad();
            s.0.borrow_mut().grad += exp * s.data().powf(exp - 1.0) * og;
        }));
        out
    }

    /// Negation: -self
    pub fn neg(&self) -> Value {
        self.mul(&Value::new(-1.0))
    }

    /// Subtraction: self - other
    pub fn sub(&self, other: &Value) -> Value {
        self.add(&other.neg())
    }

    /// Division: self / other  ==  self * other^(-1)
    pub fn div(&self, other: &Value) -> Value {
        self.mul(&other.pow(-1.0))
    }

    /// Scalar addition:  self + scalar
    pub fn add_f64(&self, scalar: f64) -> Value {
        self.add(&Value::new(scalar))
    }

    /// Scalar multiplication: self * scalar
    pub fn mul_f64(&self, scalar: f64) -> Value {
        self.mul(&Value::new(scalar))
    }

    // ------------------------------------------------------------------
    // Activation functions
    // ------------------------------------------------------------------

    /// Hyperbolic tangent activation (tanh)
    pub fn tanh(&self) -> Value {
        let x = self.data();
        let t = x.tanh();
        let out = Value::new(t);
        out.0.borrow_mut().op = "tanh".into();
        out.0.borrow_mut().prev = vec![self.clone()];

        let s = self.clone();
        let out_ref = out.clone();
        out.0.borrow_mut().backward_fn = Some(Box::new(move || {
            let og = out_ref.grad();
            // t is captured by value because it is Copy (f64)
            s.0.borrow_mut().grad += (1.0 - t * t) * og;
        }));
        out
    }

    // ------------------------------------------------------------------
    // Backpropagation
    // ------------------------------------------------------------------

    /// Runs backprop from this node back through the full computation graph.
    /// Equivalent to Python's `Value.backward()`.
    pub fn backward(&self) {
        // 1. Build topological order
        let mut topo: Vec<Value> = vec![];
        let mut visited: HashSet<usize> = HashSet::new();

        fn build_topo(v: &Value, topo: &mut Vec<Value>, visited: &mut HashSet<usize>) {
            let id = v.ptr_id();
            if !visited.contains(&id) {
                visited.insert(id);
                let children = v.0.borrow().prev.clone();
                for child in &children {
                    build_topo(child, topo, visited);
                }
                topo.push(v.clone());
            }
        }

        build_topo(self, &mut topo, &mut visited);

        // Clear gradients so a graph can be reused safely.
        for node in &topo {
            node.set_grad(0.0);
        }

        // 2. Seed gradient at the root
        self.set_grad(1.0);

        // 3. Walk in reverse topological order, calling each node's backward closure
        for node in topo.iter().rev() {
            let bfn = node.0.borrow_mut().backward_fn.take();
            if let Some(f) = bfn {
                f();
                // Put it back so the graph can be reused
                node.0.borrow_mut().backward_fn = Some(f);
            }
        }
    }
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Value(data={}, grad={})", self.data(), self.grad())
    }
}

// =============================================================================
// SECTION 2 — Neural network primitives (Neuron, Layer, MLP)
//             Equivalent to the Python Neuron / Layer / MLP classes.
// =============================================================================

use rand::rngs::StdRng;
use rand::{RngExt, SeedableRng};

static NEXT_NEURON_SEED: AtomicU64 = AtomicU64::new(43);

/// A single neuron: stores weights + bias, computes tanh(w·x + b).
pub struct Neuron {
    pub w: Vec<Value>,
    pub b: Value,
}

impl Neuron {
    pub fn new(nin: usize) -> Self {
        let mut rng = StdRng::seed_from_u64(NEXT_NEURON_SEED.fetch_add(1, Ordering::Relaxed));
        let w = (0..nin)
            .map(|_| Value::new(rng.random_range(-1.0..=1.0)))
            .collect();
        let b = Value::new(rng.random_range(-1.0..=1.0));
        Neuron { w, b }
    }

    /// Forward pass: tanh( sum(wi * xi) + b )
    pub fn call(&self, x: &[Value]) -> Value {
        assert_eq!(
            self.w.len(),
            x.len(),
            "neuron input count must match input vector length"
        );
        let act = self
            .w
            .iter()
            .zip(x.iter())
            .map(|(wi, xi)| wi.mul(xi))
            .fold(self.b.clone(), |acc, v| acc.add(&v));
        act.tanh()
    }

    /// Returns all learnable parameters (weights + bias).
    pub fn parameters(&self) -> Vec<Value> {
        let mut params = self.w.clone();
        params.push(self.b.clone());
        params
    }
}

/// A fully-connected layer of neurons.
pub struct Layer {
    pub neurons: Vec<Neuron>,
}

impl Layer {
    pub fn new(nin: usize, nout: usize) -> Self {
        Layer {
            neurons: (0..nout).map(|_| Neuron::new(nin)).collect(),
        }
    }

    /// Forward pass through every neuron in the layer.
    /// Returns a `Vec<Value>` — always consistent, no ambiguous union type.
    pub fn call(&self, x: &[Value]) -> Vec<Value> {
        self.neurons.iter().map(|n| n.call(x)).collect()
    }

    pub fn parameters(&self) -> Vec<Value> {
        self.neurons.iter().flat_map(|n| n.parameters()).collect()
    }
}

/// Multi-layer perceptron: a stack of `Layer`s.
pub struct MLP {
    pub layers: Vec<Layer>,
}

impl MLP {
    /// `nin` — number of inputs.
    /// `nouts` — list of layer sizes, e.g. `vec![4, 4, 1]`.
    pub fn new(nin: usize, nouts: &[usize]) -> Self {
        let sizes: Vec<usize> = std::iter::once(nin).chain(nouts.iter().cloned()).collect();
        let layers = sizes.windows(2).map(|w| Layer::new(w[0], w[1])).collect();
        MLP { layers }
    }

    /// Forward pass through all layers; returns the final layer's outputs.
    /// For a single-output MLP the Vec will have exactly one element.
    pub fn call(&self, x: &[Value]) -> Vec<Value> {
        let mut out: Vec<Value> = x.to_vec();
        for layer in &self.layers {
            out = layer.call(&out);
        }
        out
    }

    pub fn parameters(&self) -> Vec<Value> {
        self.layers.iter().flat_map(|l| l.parameters()).collect()
    }
}

// =============================================================================
// SECTION 3 — Loss, gradient descent, training loop
// =============================================================================

/// Mean-squared-error loss over a batch.
pub fn mse_loss(ypred: &[Value], ytrue: &[f64]) -> Value {
    assert_eq!(
        ypred.len(),
        ytrue.len(),
        "prediction and target batches must have equal lengths"
    );
    assert!(!ypred.is_empty(), "cannot compute loss for an empty batch");
    ypred
        .iter()
        .zip(ytrue.iter())
        .map(|(yout, &ygt)| yout.sub(&Value::new(ygt)).pow(2.0))
        .fold(Value::new(0.0), |acc, v| acc.add(&v))
        .mul_f64(1.0 / ypred.len() as f64)
}

/// Zero all parameter gradients before a new backward pass.
pub fn zero_grad(params: &[Value]) {
    for p in params {
        p.set_grad(0.0);
    }
}

/// Gradient descent update step:  p.data -= lr * p.grad
pub fn sgd_step(params: &[Value], lr: f64) {
    for p in params {
        let update = p.data() - lr * p.grad();
        p.set_data(update);
    }
}

#[cfg(feature = "plot")]
fn svg_escape(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

#[cfg(feature = "plot")]
fn collect_graph(
    value: &Value,
    nodes: &mut Vec<Value>,
    edges: &mut Vec<(Value, Value)>,
    seen: &mut HashSet<usize>,
) {
    if !seen.insert(value.ptr_id()) {
        return;
    }
    let children = value.0.borrow().prev.clone();
    for child in &children {
        edges.push((child.clone(), value.clone()));
        collect_graph(child, nodes, edges, seen);
    }
    nodes.push(value.clone());
}

/// Render a computation graph like micrograd.py's Graphviz `draw_dot`.
#[cfg(feature = "plot")]
pub fn draw_dot(root: &Value, filename: &str) -> Result<(), Box<dyn std::error::Error>> {
    let mut nodes = Vec::new();
    let mut edges = Vec::new();
    collect_graph(root, &mut nodes, &mut edges, &mut HashSet::new());

    fn depth(value: &Value, memo: &mut std::collections::HashMap<usize, usize>) -> usize {
        if let Some(&result) = memo.get(&value.ptr_id()) {
            return result;
        }
        let children = value.0.borrow().prev.clone();
        let result = children
            .iter()
            .map(|child| depth(child, memo) + 1)
            .max()
            .unwrap_or(0);
        memo.insert(value.ptr_id(), result);
        result
    }

    let mut depths = std::collections::HashMap::new();
    let root_depth = depth(root, &mut depths);
    let mut rows = std::collections::HashMap::<usize, usize>::new();
    let mut positions = std::collections::HashMap::new();
    for node in &nodes {
        let level = root_depth - depths[&node.ptr_id()];
        let row = rows.entry(level).or_insert(0);
        positions.insert(node.ptr_id(), (100 + level * 240, 70 + *row * 90));
        *row += 1;
    }

    let width = ((root_depth + 1) * 240 + 220).max(640);
    let height = (nodes.len().max(1) * 90 + 80).max(240);
    let mut svg = format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{width}\" height=\"{height}\">\
         <rect width=\"100%\" height=\"100%\" fill=\"white\"/>\
         <g font-family=\"sans-serif\" font-size=\"13\">"
    );

    for (child, parent) in &edges {
        let (cx, cy) = positions[&child.ptr_id()];
        let (px, py) = positions[&parent.ptr_id()];
        let op_x = px - 100;
        svg.push_str(&format!(
            "<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" stroke=\"#555\" marker-end=\"url(#arrow)\"/>",
            cx + 95,
            cy,
            op_x,
            py
        ));
        svg.push_str(&format!(
            "<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" stroke=\"#555\" marker-end=\"url(#arrow)\"/>",
            op_x + 34,
            py,
            px,
            py
        ));
    }

    svg.push_str(
        "<defs><marker id=\"arrow\" markerWidth=\"8\" markerHeight=\"8\" refX=\"7\" refY=\"3\" \
         orient=\"auto\"><path d=\"M0,0 L0,6 L7,3 z\" fill=\"#555\"/></marker></defs>",
    );

    for node in &nodes {
        let (x, y) = positions[&node.ptr_id()];
        let inner = node.0.borrow();
        let label = if inner.label.is_empty() {
            " ".to_string()
        } else {
            inner.label.clone()
        };
        svg.push_str(&format!(
            "<rect x=\"{x}\" y=\"{}\" width=\"190\" height=\"48\" rx=\"4\" fill=\"#eef5ff\" stroke=\"#3465a4\"/>\
             <text x=\"{}\" y=\"{}\" text-anchor=\"middle\">{}</text>\
             <text x=\"{}\" y=\"{}\" text-anchor=\"middle\" font-size=\"11\">data: {:.4} | grad: {:.4}</text>",
            y - 24,
            x + 95,
            y - 4,
            svg_escape(&label),
            x + 95,
            y + 14,
            inner.data,
            inner.grad
        ));
        if !inner.op.is_empty() {
            let op_x = x - 38;
            svg.push_str(&format!(
                "<rect x=\"{}\" y=\"{}\" width=\"34\" height=\"28\" fill=\"#fff4cc\" stroke=\"#a67c00\"/>\
                 <text x=\"{}\" y=\"{}\" text-anchor=\"middle\">{}</text>",
                op_x,
                y - 14,
                op_x + 17,
                y + 5,
                svg_escape(&inner.op)
            ));
        }
    }
    svg.push_str("</g></svg>");
    fs::write(filename, svg)?;
    println!("Saved {filename}");
    Ok(())
}

// =============================================================================
// SECTION 4 — PyTorch equivalent using the Burn crate
//             Mirrors the `import torch` section of the original Python file.
// =============================================================================

// Burn is enabled in Cargo.toml with its ndarray backend.

use burn::backend::NdArray;
use burn::tensor::Tensor;

type B = NdArray<f64>;

/// Replicates the single-neuron forward + backward check that was done with
/// PyTorch in the original Python file.
///
/// Inputs:  x1=2.0, x2=0.0
/// Weights: w1=-3.0, w2=1.0
/// Bias:    b=6.8813735870195432
/// Output:  tanh(w1*x1 + w2*x2 + b)
pub fn burn_single_neuron_check() {
    // Build tensors — shape [1] for each scalar, requires_grad handled by Burn's autodiff.
    // Burn's NdArray backend does not yet expose per-tensor grad control at the scalar
    // level the same way PyTorch does, so we demonstrate the forward pass and note where
    // gradients would be read back in a full autodiff backend (e.g. burn::backend::Autodiff<NdArray>).

    let device = burn::backend::ndarray::NdArrayDevice::Cpu;

    let x1: Tensor<B, 1> = Tensor::from_floats([2.0_f64], &device);
    let x2: Tensor<B, 1> = Tensor::from_floats([0.0_f64], &device);
    let w1: Tensor<B, 1> = Tensor::from_floats([-3.0_f64], &device);
    let w2: Tensor<B, 1> = Tensor::from_floats([1.0_f64], &device);
    let b: Tensor<B, 1> = Tensor::from_floats([6.881_373_587_019_543_f64], &device);

    let n = w1 * x1 + w2 * x2 + b;
    let o = n.tanh();

    println!("[Burn] Single neuron output: {:?}", o.to_data());
    // Expected: ~0.7071  (matches Python/PyTorch output)
}

// =============================================================================
// SECTION 5 — Optional plot helper (replaces matplotlib)
