#[cfg(feature = "plot")]
pub fn plot_curves() -> Result<(), Box<dyn std::error::Error>> {
    use plotters::prelude::*;
    {
        let root = SVGBackend::new("quadratic_curve.svg", (640, 480)).into_drawing_area();
        root.fill(&WHITE)?;
        let mut chart = ChartBuilder::on(&root)
            .caption("f(x) = 3x² - 4x + 5", ("sans-serif", 30))
            .margin(20)
            .x_label_area_size(30)
            .y_label_area_size(40)
            .build_cartesian_2d(-5.0_f64..5.0_f64, 0.0_f64..100.0_f64)?;
        chart.configure_mesh().draw()?;
        chart.draw_series(LineSeries::new(
            (-20..=20).map(|i| {
                let x = i as f64 / 4.0;
                (x, 3.0 * x * x - 4.0 * x + 5.0)
            }),
            &BLUE,
        ))?;
        root.present()?;
    }
    {
        let root = SVGBackend::new("tanh_curve.svg", (640, 480)).into_drawing_area();
        root.fill(&WHITE)?;
        let mut chart = ChartBuilder::on(&root)
            .caption("tanh activation", ("sans-serif", 30))
            .margin(20)
            .x_label_area_size(30)
            .y_label_area_size(30)
            .build_cartesian_2d(-5.0_f64..5.0_f64, -1.2_f64..1.2_f64)?;
        chart.configure_mesh().draw()?;
        chart.draw_series(LineSeries::new(
            (-500..=500).map(|x| {
                let xf = x as f64 / 100.0;
                (xf, xf.tanh())
            }),
            &RED,
        ))?;
        root.present()?;
    }
    println!("Saved quadratic_curve.svg and tanh_curve.svg");
    Ok(())
}

#[cfg(feature = "plot-window")]
pub fn show_plot_window() -> Result<(), Box<dyn std::error::Error>> {
    use minifb::{Key, Window, WindowOptions};
    use plotters::prelude::*;

    const WIDTH: usize = 1000;
    const HEIGHT: usize = 800;
    let mut pixels = vec![0_u32; WIDTH * HEIGHT];
    let mut rgb = vec![255_u8; WIDTH * HEIGHT * 3];

    {
        let root =
            BitMapBackend::with_buffer(&mut rgb, (WIDTH as u32, HEIGHT as u32)).into_drawing_area();
        root.fill(&WHITE)?;
        let areas = root.split_evenly((2, 1));

        let mut quadratic = ChartBuilder::on(&areas[0])
            .caption("f(x) = 3x² - 4x + 5", ("sans-serif", 24))
            .margin(15)
            .x_label_area_size(30)
            .y_label_area_size(40)
            .build_cartesian_2d(-5.0_f64..5.0_f64, 0.0_f64..100.0_f64)?;
        quadratic.configure_mesh().draw()?;
        quadratic.draw_series(LineSeries::new(
            (-20..=20).map(|i| {
                let x = i as f64 / 4.0;
                (x, 3.0 * x * x - 4.0 * x + 5.0)
            }),
            &BLUE,
        ))?;

        let mut tanh = ChartBuilder::on(&areas[1])
            .caption("tanh activation", ("sans-serif", 24))
            .margin(15)
            .x_label_area_size(30)
            .y_label_area_size(30)
            .build_cartesian_2d(-5.0_f64..5.0_f64, -1.2_f64..1.2_f64)?;
        tanh.configure_mesh().draw()?;
        tanh.draw_series(LineSeries::new(
            (-500..=500).map(|i| {
                let x = i as f64 / 100.0;
                (x, x.tanh())
            }),
            &RED,
        ))?;
        root.present()?;
    }

    for (index, pixel) in pixels.iter_mut().enumerate() {
        let offset = index * 3;
        *pixel = (u32::from(rgb[offset]) << 16)
            | (u32::from(rgb[offset + 1]) << 8)
            | u32::from(rgb[offset + 2]);
    }

    let mut window = Window::new(
        "micrograd visualizations",
        WIDTH,
        HEIGHT,
        WindowOptions::default(),
    )?;
    while window.is_open() && !window.is_key_down(Key::Escape) {
        window.update_with_buffer(&pixels, WIDTH, HEIGHT)?;
    }
    Ok(())
}

// =============================================================================
// SECTION 6 — main()  (ties everything together, mirrors the Python script body)
// =============================================================================

fn main() {
    // ---------------------------------------------------------------
    // 6a. Evaluate the quadratic  f(x) = 3x² - 4x + 5  at x=3
    // ---------------------------------------------------------------
    let f = |x: f64| 3.0 * x * x - 4.0 * x + 5.0;
    println!("f(3.0) = {}", f(3.0)); // expected: 20.0

    // ---------------------------------------------------------------
    // 6b. Numerical derivative of f at x = 2/3
    // ---------------------------------------------------------------
    let h = 1e-8_f64;
    let x = 2.0 / 3.0;
    let slope = (f(x + h) - f(x)) / h;
    println!("f'(2/3) ≈ {:.6}", slope); // expected: 0.0 (minimum of f)

    // ---------------------------------------------------------------
    // 6c. Manual gradient for  y = a*b + c   w.r.t. c
    // ---------------------------------------------------------------
    let a = 2.0_f64;
    let b = -3.0_f64;
    let c = 10.0_f64;
    let y = a * b + c;
    let y1 = a * b + (c + h);
    let grad_c = (y1 - y) / h;
    println!("dy/dc = {:.6}", grad_c); // expected: 1.0

    // ---------------------------------------------------------------
    // 6d. Build the computation graph and run backprop
    //     L = g * (a + b*c)  — same graph as the Python walkthrough
    // ---------------------------------------------------------------
    let va = Value::with_label(2.0, "a");
    let vb = Value::with_label(-3.0, "b");
    let vc = Value::with_label(10.0, "c");
    let vg = Value::with_label(-2.0, "g");

    let e = vb.mul(&vc);
    e.set_label("e");
    let d = va.add(&e);
    d.set_label("d");
    let l = vg.mul(&d);
    l.set_label("L");

    l.backward();

    println!("\n--- Autograd gradients ---");
    println!("a.grad = {:.4}  (expected  -2.0)", va.grad());
    println!("b.grad = {:.4}  (expected -20.0)", vb.grad());
    println!("c.grad = {:.4}  (expected   6.0)", vc.grad());
    println!("g.grad = {:.4}  (expected -28.0)", vg.grad());
    #[cfg(feature = "plot")]
    draw_dot(&l, "graph_value.svg").expect("failed to render value graph");

    // ---------------------------------------------------------------
    // 6e. Single neuron with tanh  (replicates the Python walkthrough)
    //     x1=2, x2=0, w1=-3, w2=1, b=6.88137…  → o ≈ 0.7071
    // ---------------------------------------------------------------
    let x1 = Value::with_label(2.0, "x1");
    let x2 = Value::with_label(0.0, "x2");
    let w1 = Value::with_label(-3.0, "w1");
    let w2 = Value::with_label(1.0, "w2");
    let bias = Value::with_label(6.881_373_587_019_543, "b");

    let x1w1 = x1.mul(&w1);
    x1w1.set_label("x1w1");
    let x2w2 = x2.mul(&w2);
    x2w2.set_label("x2w2");
    let sum_xw = x1w1.add(&x2w2);
    sum_xw.set_label("x1w1+x2w2");
    let n = sum_xw.add(&bias);
    n.set_label("n");
    let o = n.tanh();
    o.set_label("o");

    o.backward();

    println!("\n--- Single neuron (tanh) ---");
    println!("o    = {:.6}  (expected ≈ 0.707107)", o.data());
    println!("x1.grad = {:.4}  (expected -1.5)", x1.grad());
    println!("w1.grad = {:.4}  (expected  1.0)", w1.grad());
    println!("x2.grad = {:.4}  (expected  0.5)", x2.grad());
    println!("w2.grad = {:.4}  (expected  0.0)", w2.grad());
    #[cfg(feature = "plot")]
    draw_dot(&o, "graph_neuron.svg").expect("failed to render neuron graph");

    // ---------------------------------------------------------------
    // 6f. Burn crate equivalent of the PyTorch single-neuron check
    // ---------------------------------------------------------------
    println!("\n--- Burn single-neuron check ---");
    burn_single_neuron_check();

    // ---------------------------------------------------------------
    // 6g. Build MLP and train for 20 steps
    //     Architecture: 3 inputs → [4, 4, 1]
    //     Dataset: 4 samples, binary targets  [1, -1, -1, 1]
    // ---------------------------------------------------------------
    let mlp = MLP::new(3, &[4, 4, 1]);

    let xs: Vec<Vec<Value>> = vec![
        vec![Value::new(2.0), Value::new(3.0), Value::new(-1.0)],
        vec![Value::new(3.0), Value::new(-1.0), Value::new(0.5)],
        vec![Value::new(0.5), Value::new(1.0), Value::new(1.0)],
        vec![Value::new(1.0), Value::new(1.0), Value::new(-1.0)],
    ];
    let ys: Vec<f64> = vec![1.0, -1.0, -1.0, 1.0];

    #[cfg(feature = "plot")]
    {
        let first_output = mlp.call(&xs[0]).into_iter().next().unwrap();
        draw_dot(&first_output, "graph_mlp.svg").expect("failed to render MLP graph");
        let initial_predictions: Vec<Value> = xs
            .iter()
            .map(|x| mlp.call(x).into_iter().next().unwrap())
            .collect();
        let initial_loss = mse_loss(&initial_predictions, &ys);
        let params = mlp.parameters();
        zero_grad(&params);
        initial_loss.backward();
        draw_dot(&initial_loss, "graph_loss.svg").expect("failed to render loss graph");
    }

    println!("\n--- MLP training (20 steps, lr=0.05) ---");
    for k in 0..20 {
        // Forward pass — unwrap the single output per sample
        let ypred: Vec<Value> = xs
            .iter()
            .map(|x| mlp.call(x).into_iter().next().unwrap())
            .collect();

        // Loss
        let loss = mse_loss(&ypred, &ys);

        // Backward pass
        let params = mlp.parameters();
        zero_grad(&params);
        loss.backward();

        // SGD update
        sgd_step(&params, 0.05);

        println!("step {:2}  loss = {:.6}", k, loss.data());
    }

    // ---------------------------------------------------------------
    // 6h. Per-sample losses after training
    // ---------------------------------------------------------------
    let ypred_final: Vec<Value> = xs
        .iter()
        .map(|x| mlp.call(x).into_iter().next().unwrap())
        .collect();

    println!("\n--- Per-sample squared errors after training ---");
    for (i, (yout, &ygt)) in ypred_final.iter().zip(ys.iter()).enumerate() {
        let err = yout.sub(&Value::new(ygt)).pow(2.0);
        println!(
            "sample {}: pred={:.4}  target={:.1}  err²={:.6}",
            i,
            yout.data(),
            ygt,
            err.data()
        );
    }

    // ---------------------------------------------------------------
    // 6i. Optional: render curves and computation graphs
    // ---------------------------------------------------------------
    #[cfg(all(feature = "plot", not(feature = "plot-window")))]
    plot_curves().expect("plot rendering failed");
    #[cfg(feature = "plot-window")]
    show_plot_window().expect("plot window failed");
}
